1	use std::collections::BTreeMap;
2	
3	pub struct Item {
4	    pub item_type: String,
5	    pub material: String,
6	    pub enchantment: u32,
7	    pub cursed: bool,
8	}
9	
10	const PROCESSING_FEE: u64 = 5;
11	
12	const SWORD_BASE_PREMIUM: u64 = 100;
13	const AMULET_BASE_PREMIUM: u64 = 60;
14	const STAFF_BASE_PREMIUM: u64 = 80;
15	const POTION_BASE_PREMIUM: u64 = 40;
16	const COMPONENT_BASE_PREMIUM: u64 = 25;
17	const COMPONENT_BLOCK_BASE_PREMIUM: u64 = 60;
18	const COMPONENT_BLOCK_SIZE: usize = 3;
19	const CURSE_SURCHARGE_PERCENT: u64 = 50;
20	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT: u64 = 30;
21	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
22	const FIRST_INSURANCE_SURCHARGE_PERCENT: u64 = 10;
23	
24	/// The MHPCO price list: the base premium the catalogue lists for one item.
25	fn base_premium(item: &Item) -> u64 {
26	    match item.item_type.as_str() {
27	        "amulet" => AMULET_BASE_PREMIUM,
28	        "staff" => STAFF_BASE_PREMIUM,
29	        "potion" => POTION_BASE_PREMIUM,
30	        "rune" | "moonstone" => COMPONENT_BASE_PREMIUM,
31	        _ => SWORD_BASE_PREMIUM,
32	    }
33	}
34	
35	/// The building-block offer is reserved for a group of exactly 3 alike
36	/// components; a larger group does not qualify, it is priced per component.
37	fn qualifies_as_building_block(alike_component_count: usize) -> bool {
38	    alike_component_count == COMPONENT_BLOCK_SIZE
39	}
40	
41	/// The price the MHPCO charges for one group of alike components: the
42	/// building-block offer when the group qualifies, otherwise per component.
43	fn component_group_base_premium(count: usize) -> u64 {
44	    if qualifies_as_building_block(count) {
45	        COMPONENT_BLOCK_BASE_PREMIUM
46	    } else {
47	        count as u64 * COMPONENT_BASE_PREMIUM
48	    }
49	}
50	
51	/// Two components are "alike" when they share this key. For the MHPCO,
52	/// alike means the very same catalogue type: a rune and a moonstone are
53	/// never alike, so mixed component types form no building block.
54	fn alike_group_key(item: &Item) -> &str {
55	    &item.item_type
56	}
57	
58	/// The policy base premium: the sum of all insured items' base premiums,
59	/// with alike components priced per group so a block can be recognised.
60	fn policy_base_premium(items: &[Item]) -> u64 {
61	    let mut main_items_total = 0;
62	    let mut alike_component_counts: BTreeMap<&str, usize> = BTreeMap::new();
63	    for item in items {
64	        if is_component(item) {
65	            *alike_component_counts.entry(alike_group_key(item)).or_insert(0) += 1;
66	        } else {
67	            main_items_total += base_premium(item);
68	        }
69	    }
70	
71	    main_items_total
72	        + alike_component_counts
73	            .values()
74	            .map(|count| component_group_base_premium(*count))
75	            .sum::<u64>()
76	}
77	
78	/// Components, such as runes and moonstones, are the parts the MHPCO insures
79	/// alongside main items and the only items the building-block offer covers.
80	fn is_component(item: &Item) -> bool {
81	    matches!(item.item_type.as_str(), "rune" | "moonstone")
82	}
83	
84	/// Intermediate amounts stay fractional; only the final premium is rounded.
85	/// In the MHPCO's favor means upwards for a premium the customer owes.
86	fn premium_rounded_in_mhpco_favor(amount: f64) -> u64 {
87	    amount.ceil() as u64
88	}
89	
90	/// Every item in a quote is treated as a first insurance, so the initial
91	/// assessment surcharge is charged on the whole policy base premium.
92	fn first_insurance_surcharge(policy_base_premium: f64) -> f64 {
93	    policy_base_premium * FIRST_INSURANCE_SURCHARGE_PERCENT as f64 / 100.0
94	}
95	
96	/// The MHPCO charges a high-enchantment risk surcharge on items it considers
97	/// highly enchanted. This is the premium-side threshold; the claim-side
98	/// reimbursement clause judges enchantment by its own, stricter threshold.
99	fn is_highly_enchanted(item: &Item) -> bool {
100	    item.enchantment >= HIGH_ENCHANTMENT_LEVEL
101	}
102	
103	/// An item-specific risk surcharge is charged on the base premium of the
104	/// affected item, never on the policy total.
105	fn risk_surcharge_on_base_premium(item: &Item, surcharge_percent: u64) -> f64 {
106	    base_premium(item) as f64 * surcharge_percent as f64 / 100.0
107	}
108	
109	/// The risk surcharge one item carries. Risks the MHPCO recognises stack: an
110	/// item that brings two of them is surcharged for each.
111	fn item_risk_surcharge(item: &Item) -> f64 {
112	    let mut surcharge = 0.0;
113	    if item.cursed {
114	        surcharge += risk_surcharge_on_base_premium(item, CURSE_SURCHARGE_PERCENT);
115	    }
116	    if is_highly_enchanted(item) {
117	        surcharge += risk_surcharge_on_base_premium(item, HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
118	    }
119	    surcharge
120	}
121	
122	/// Item-specific modifiers apply to the base premium of the affected item,
123	/// never to the policy total, so the policy owes the sum of the items' own
124	/// risk surcharges.
125	fn item_risk_surcharges(items: &[Item]) -> f64 {
126	    items.iter().map(item_risk_surcharge).sum()
127	}
128	
129	pub fn quote_premium(items: &[Item]) -> u64 {
130	    let policy_base_premium = policy_base_premium(items) as f64;
131	    premium_rounded_in_mhpco_favor(
132	        policy_base_premium
133	            + item_risk_surcharges(items)
134	            + first_insurance_surcharge(policy_base_premium)
135	            + PROCESSING_FEE as f64,
136	    )
137	}
